export const QUESTION_MAP: Map<string, Question> = new Map(
  QUESTIONS.map((q) => [q.id, q])
)

export function getTest(id: string): TestDefinition | undefined {
  return TESTS.find((t) => t.id === id)
}

export function getQuestions(testId: string): Question[] {
  const test = getTest(testId)
  if (!test) return []
  return test.questionIds
    .map((qid) => QUESTION_MAP.get(qid))
    .filter((q): q is Question => q !== undefined)
}

export function testMarks(testId: string): number {
  return getQuestions(testId).reduce((sum, q) => sum + (q.marks || 1), 0)
}
